public static boolean isRoleActiveForCurrentUser(str _roleAotName)
{
    SecurityRole securityRole;
    SecurityUserRole securityUserRole;

    select firstonly RecId from securityUserRole
      where securityUserRole.User == curUserId()
         && securityUserRole.AssignmentStatus == RoleAssignmentStatus::Enabled
      join RecId from securityRole
          where securityRole.RecId == securityUserRole.SecurityRole
             && securityRole.AotName == _roleAotName;

    return securityUserRole.RecId != 0;
}

public static str getTAMRebateModuleRestrictionHelpText()
{
    Set     tableSet = new Set(Types::String);
    str     roleName = 'METTAMRebateModulePolicyRole';
    str     roleLabel;
    str     tableListStr;
    str     helpText;

    // Get role label
    roleLabel = METSecurityPolicyHelper::getRoleLabel(roleName);

    // Collect all tables from all policies into a single set
    METSecurityPolicyHelper::collectPolicyTables('METTAMRebateDealModulePolicy', tableSet);
    METSecurityPolicyHelper::collectPolicyTables('METTAMRebateTableModulePolicy', tableSet);

    // Build comma-separated table list with "and" before last item
    tableListStr = METSecurityPolicyHelper::formatTableList(tableSet);

    helpText = strFmt("Role: %1 (%2). Tables: %3.", roleLabel, roleName, tableListStr);

    return helpText;
}

