public static str getSiteRestrictionHelpText()
{
    Set     tableSet = new Set(Types::String);
    str     roleName = 'METInventSitePolicyRole';
    str     roleLabel;
    str     tableListStr;
    str     helpText;

    // Get role label
    roleLabel = METSecurityPolicyHelper::getRoleLabel(roleName);

    // Collect all tables from all policies into a single set
    METSecurityPolicyHelper::collectPolicyTables('METSiteInventSitePolicy', tableSet);
    METSecurityPolicyHelper::collectPolicyTables('METSiteInventDimPolicy', tableSet);
    METSecurityPolicyHelper::collectPolicyTables('METSiteSalesTablePolicy', tableSet);

    // Build comma-separated table list with "and" before last item
    tableListStr = METSecurityPolicyHelper::formatTableList(tableSet);

    helpText = strFmt("Role: %1 (%2). Tables: %3.", roleLabel, roleName, tableListStr);
    helpText += '\n';
    helpText += "Note: Add empty value to see records with no site.";

    return helpText;
}

private static str getRoleLabel(str _roleName)
{
    SecurityRole    securityRole;
    str             roleLabel;

    select firstonly Name from securityRole
        where securityRole.AotName == _roleName;

    if (securityRole)
    {
        roleLabel = securityRole.Name;
    }

    return roleLabel ? roleLabel : _roleName;
}

private static void collectPolicyTables(str _policyName, Set _tableSet)
{
    TreeNode    policyNode;
    TreeNode    constraintsNode;
    str         aotPath;

    aotPath    = strFmt(@"\Security\Policies\%1", _policyName);
    policyNode = TreeNode::findNode(aotPath);

    if (!policyNode)
    {
        return;
    }

    // Add primary table if constrained
    if (policyNode.AOTgetProperty('ConstrainedTable') == 'Yes')
    {
        _tableSet.add(policyNode.AOTgetProperty('PrimaryTable'));
    }

    // Traverse constrained tables (including nested)
    constraintsNode = policyNode.AOTfindChild('Constrained Tables');

    if (constraintsNode)
    {
        METSecurityPolicyHelper::traverseTableNodes(constraintsNode, _tableSet);
    }
}

private static void traverseTableNodes(TreeNode _parentNode, Set _tableSet)
{
    TreeNode    currentNode;
    str         tableName;

    currentNode = _parentNode.AOTfirstChild();

    while (currentNode)
    {
        tableName = currentNode.AOTgetProperty('Name');

        if (!tableName)
        {
            tableName = currentNode.AOTname();
        }

        if (tableName)
        {
            _tableSet.add(tableName);
        }

        // Recursively process nested constrained tables
        if (currentNode.AOTfirstChild())
        {
            METSecurityPolicyHelper::traverseTableNodes(currentNode, _tableSet);
        }

        currentNode = currentNode.AOTnextSibling();
    }
}

private static str formatTableList(Set _tableSet)
{
    SetEnumerator   enumerator;
    List            tableList;
    ListIterator    iterator;
    str             result;
    int             tableCount;
    int             i;

    tableList = new List(Types::String);
    enumerator = _tableSet.getEnumerator();

    // Convert set to list for ordered iteration
    while (enumerator.moveNext())
    {
        tableList.addEnd(enumerator.current());
    }

    tableCount = tableList.elements();
    iterator = new ListIterator(tableList);
    i = 0;

    while (iterator.more())
    {
        i++;

        if (i == tableCount && tableCount > 1)
        {
            result += 'and ' + iterator.value();
        }
        else if (i == tableCount)
        {
            result += iterator.value();
        }
        else
        {
            result += iterator.value() + ', ';
        }

        iterator.next();
    }

    return result;
}
